// ---- the kernel ----
__global__ void __launch_bounds__(256, 1)
    layer_kernel(const __grid_constant__ static_mk::Maps maps,
                 static_mk::G g,
                 StaticTask const *static_tasks) {
  static_mk::KernelLocals L;
  static_mk::kernel_begin(g, L);
  StaticTask const *my =
      static_tasks + blockIdx.x * (static_mk::MAX_TASKS_PER_SM);
  bool warm_9 = false;  // a task of node 9 ran on this SM: its code is in the
                        // instruction cache
  bool warm_26 = false; // a task of node 26 ran on this SM: its code is in the
                        // instruction cache
  bool warm_32 = false; // a task of node 32 ran on this SM: its code is in the
                        // instruction cache
  bool warm_38 = false; // a task of node 38 ran on this SM: its code is in the
                        // instruction cache
  for (int ti = 0; ti < static_mk::MAX_TASKS_PER_SM; ti++) {
    StaticTask const tk = my[ti];
    if (tk.node < 0) {
      break;
    }
    switch (tk.node) {
      case 3:
        static_mk::run_act_quant<StaticNode<8, 2, 1, 0, 1>,
                                 StaticParams<5120>,
                                 StaticBufSlots<0>,
                                 StaticMapSlots<>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 7:
        static_mk::run_gemm_fp8_tile<StaticNode<10, 4, 1, -1, 2>,
                                     StaticParams<0, 5120, 1280, 1>,
                                     StaticBufSlots<>,
                                     StaticMapSlots<0, 1, 2, 3>,
                                     StaticNode<8, 2, 1, 0, 1, 5120>,
                                     StaticNode<0, 0, 0>,
                                     StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 9:
        static_mk::run_q_norm<StaticNode<8, 1, 1, 32, 4>,
                              StaticParams<1280, 507307272>,
                              StaticBufSlots<3>,
                              StaticMapSlots<>,
                              StaticNode<10, 4, 1, -1, 2, 0, 5120, 1280, 1>,
                              StaticNode<0, 0, 0>>(maps, g, L, tk, warm_9);
        warm_9 = true;
        break;
      case 13:
        static_mk::run_gemm_fp8_tile<
            StaticNode<64, 1, 1, -1, 5>,
            StaticParams<0, 1280, 8192, 1, 1>,
            StaticBufSlots<>,
            StaticMapSlots<4, 5, 6, 7>,
            StaticNode<8, 1, 1, 32, 4, 1280, 507307272>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 19:
        static_mk::run_gemm_fp8_tile<StaticNode<4, 2, 1, -1, 6>,
                                     StaticParams<0, 5120, 512, 1>,
                                     StaticBufSlots<>,
                                     StaticMapSlots<8, 9, 2, 3>,
                                     StaticNode<8, 2, 1, 0, 1, 5120>,
                                     StaticNode<0, 0, 0>,
                                     StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 22:
        static_mk::run_kv_post<StaticNode<8, 1, 1, 64, -1>,
                               StaticParams<512, 128, 64, 507307272>,
                               StaticBufSlots<7, 8, 9, 10>,
                               StaticMapSlots<>,
                               StaticNode<4, 2, 1, -1, 6, 0, 5120, 512, 1>,
                               StaticNode<0, 0, 0>,
                               StaticNode<0, 0, 0>,
                               StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 26:
        static_mk::run_sparse_attn<
            StaticNode<8, 1, 1, 96, 12>,
            StaticParams<16, 512, 128, 64, 1026884851>,
            StaticBufSlots<10, 8, 9, 11>,
            StaticMapSlots<>,
            StaticNode<64, 1, 1, -1, 5, 0, 1280, 8192, 1, 1>,
            StaticNode<8, 1, 1, 64, -1, 512, 128, 64, 507307272>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>>(maps, g, L, tk, warm_26);
        warm_26 = true;
        break;
      case 30:
        static_mk::run_gemm_fp8_tile<
            StaticNode<16, 4, 1, -1, 13>,
            StaticParams<0, 4096, 2048, 2>,
            StaticBufSlots<>,
            StaticMapSlots<10, 11, 12, 13>,
            StaticNode<8, 1, 1, 96, 12, 16, 512, 128, 64, 1026884851>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 32:
        static_mk::run_act_quant<
            StaticNode<8, 1, 1, 128, 14>,
            StaticParams<2048>,
            StaticBufSlots<>,
            StaticMapSlots<>,
            StaticNode<16, 4, 1, -1, 13, 0, 4096, 2048, 2>>(
            maps, g, L, tk, warm_32);
        warm_32 = true;
        break;
      case 36:
        static_mk::run_gemm_fp8_tile<StaticNode<40, 4, 1, -1, 15>,
                                     StaticParams<0, 2048, 5120, 1>,
                                     StaticBufSlots<>,
                                     StaticMapSlots<14, 15, 16, 17>,
                                     StaticNode<8, 1, 1, 128, 14, 2048>,
                                     StaticNode<0, 0, 0>,
                                     StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 38:
        static_mk::run_sum_store<
            StaticNode<40, 1, 1, 160, -1>,
            StaticParams<5120>,
            StaticBufSlots<16>,
            StaticMapSlots<>,
            StaticNode<40, 4, 1, -1, 15, 0, 2048, 5120, 1>>(
            maps, g, L, tk, warm_38);
        warm_38 = true;
        break;
    }
  }
  static_mk::kernel_end(g, L);
}

// ---- host: all GPUs of this process ----
#include "mirage/static_megakernel/host.cuh"
#include <Python.h>
#define ST_CK(x)                                                               \
  do {                                                                         \
    cudaError_t e_ = (x);                                                      \
    if (e_ != cudaSuccess) {                                                   \
      fprintf(stderr,                                                          \
              "layer: %s @%d: %s\n",                                           \
              #x,                                                              \
              __LINE__,                                                        \
              cudaGetErrorString(e_));                                         \
      exit(1);                                                                 \
    }                                                                          \
  } while (0)
static StaticTask const *const static_tasks_of[static_mk::GPUS] = {
    static_tasks_gpu0};
static int const *const static_list_begin[static_mk::GPUS] = {
    static_list_begin_gpu0};
struct StaticGpu {
  cudaStream_t stream = nullptr;
  cudaEvent_t start =
      nullptr; // recorded right before the kernel (static_elapsed)
  cudaEvent_t end = nullptr;   // recorded after the kernel (static_wait,
                               // static_done, static_elapsed)
  StaticTask *tasks = nullptr; // the per-SM task table on the GPU
  unsigned long long *times = nullptr; // timing build: the per-task times
};
#define STATIC_PROFILE 0
#if STATIC_PROFILE
#define STATIC_TIMES_ARG , s.times
#else
#define STATIC_TIMES_ARG
#endif
static size_t const static_times_count =
    (size_t)static_mk::NSM *
    (static_mk::MAX_TASKS_PER_SM)*11; // timing build: per SM, per list entry
static std::vector<StaticGpu> g_st;
static StaticContext g_ctx;
static unsigned long long g_launches = 0;

// per GPU: a stream, two events, the kernel's shared memory size, the per-SM
// task table on the GPU (max_tasks entries per SM: the SM's list, then node =
// -1); the view the host code gets (its tensors); then static_host_init
static void
    static_init(std::vector<std::map<std::string, void *>> const &tensors) {
  int const n = static_mk::GPUS;
  if ((int)tensors.size() != n) {
    fprintf(stderr,
            "layer: built for %d GPUs, got tensors for %zu\n",
            n,
            tensors.size());
    exit(1);
  }
  g_st.assign(n, StaticGpu());
  g_ctx.num_gpus = n;
  g_ctx.num_lists = static_mk::NSM;
  g_ctx.gpus.assign(n, StaticGpuView());
  for (int g = 0; g < n; g++) {
    ST_CK(cudaSetDevice(g));
    ST_CK(cudaStreamCreate(&g_st[g].stream));
    ST_CK(cudaEventCreate(&g_st[g].start));
    ST_CK(cudaEventCreate(&g_st[g].end));
    ST_CK(cudaFuncSetAttribute(layer_kernel,
                               cudaFuncAttributeMaxDynamicSharedMemorySize,
                               (int)(STATIC_SMEM_BYTES)));
    int const max_tasks = (int)(static_mk::MAX_TASKS_PER_SM);
    std::vector<StaticTask> table((size_t)static_mk::NSM * max_tasks,
                                  StaticTask{-1, 0, 0, 0});
    for (int sm = 0; sm < static_mk::NSM; sm++) {
      int const b = static_list_begin[g][sm],
                n = static_list_begin[g][sm + 1] - b;
      if (n > max_tasks - 1) {
        fprintf(stderr,
                "layer: GPU %d SM %d: %d tasks, at most %d\n",
                g,
                sm,
                n,
                max_tasks - 1);
        exit(1);
      }
      for (int i = 0; i < n; i++) {
        table[(size_t)sm * max_tasks + i] = static_tasks_of[g][b + i];
      }
    }
    ST_CK(cudaMalloc(&g_st[g].tasks, table.size() * sizeof(StaticTask)));
    ST_CK(cudaMemcpy(g_st[g].tasks,
                     table.data(),
                     table.size() * sizeof(StaticTask),
                     cudaMemcpyHostToDevice));
    StaticGpuView &v = g_ctx.gpus[g];
    v.gpu = g;
    v.tensors = tensors[g];
  }
  static_host_init(g_ctx,
                   std::map<std::string, std::string>{
                       {"buf.0", "tensor x 40960 -1 0"},
                       {"buf.1", "out x_q 61440 -1 0"},
                       {"buf.2", "out wq_a_part 163840 255 1"},
                       {"buf.3", "tensor q_norm_weight 1280 -1 0"},
                       {"buf.4", "out qr_q 15360 -1 0"},
                       {"buf.5", "out wq_b_part 262144 255 1"},
                       {"buf.6", "out wkv_part 32768 255 1"},
                       {"buf.7", "tensor kv_norm_weight 512 -1 0"},
                       {"buf.8", "tensor positions 8 -1 0"},
                       {"buf.9", "tensor freqs_cis 278528 -1 0"},
                       {"buf.10", "tensor window_cache 540672 -1 0"},
                       {"buf.11", "tensor attn_sink 16 -1 0"},
                       {"buf.12", "out o_q 98304 -1 0"},
                       {"buf.13", "out wo_a_part 262144 255 1"},
                       {"buf.14", "out oa_q 24576 -1 0"},
                       {"buf.15", "out wo_b_part 655360 255 1"},
                       {"buf.16", "tensor y 40960 -1 0"},
                       {"map.0", "w8kt t:wq_a_weight 5120 1280 2"},
                       {"map.1", "sf t:wq_a_scales 400 2"},
                       {"map.2", "act8kt t:x_q 5120 8 2"},
                       {"map.3", "sf b:1+40960 40 2"},
                       {"map.4", "w8kt t:wq_b_weight 1280 8192 2"},
                       {"map.5", "sf t:wq_b_scales 640 2"},
                       {"map.6", "act8kt t:qr_q 1280 8 2"},
                       {"map.7", "sf b:4+10240 10 2"},
                       {"map.8", "w8kt t:wkv_weight 5120 512 2"},
                       {"map.9", "sf t:wkv_scales 160 2"},
                       {"map.10", "w8kt t:wo_a_weight 4096 2048 2"},
                       {"map.11", "sf t:wo_a_scales 512 2"},
                       {"map.12", "act8kt t:o_q 8192 8 2"},
                       {"map.13", "sf b:12+65536 64 2"},
                       {"map.14", "w8kt t:wo_b_weight 2048 5120 2"},
                       {"map.15", "sf t:wo_b_scales 640 2"},
                       {"map.16", "act8kt t:oa_q 2048 8 2"},
                       {"map.17", "sf b:14+16384 16 2"}});
  // timing build: the times buffer is allocated after the layer's buffers, so
  // those keep the addresses of the normal build (the buffers' addresses change
  // the layer's time)
  if (STATIC_PROFILE) {
    for (int g = 0; g < n; g++) {
      ST_CK(cudaSetDevice(g));
      ST_CK(cudaMalloc(&g_st[g].times,
                       static_times_count * sizeof(unsigned long long)));
    }
  }
}

// one launch on every GPU: per GPU the resets on its stream; wait for every GPU
// (so all GPUs start together); then per GPU: event, kernel, event. Serving
// mode (STATIC_RESET_IN_KERNEL: the kernel resets its own buffers): no host
// step and no host wait; per GPU on its stream the flush of flush_bytes (> 0;
// L2 emptied) and the GPUs' line-up (host.cuh static_host_prelude), then event,
// kernel, event (the events time the launch as a server sees it:
// static_elapsed)
static void static_launch(size_t flush_bytes) {
  int const n = (int)g_st.size();
  for (int g = 0; g < n; g++) {
    StaticGpu &s = g_st[g];
    ST_CK(cudaSetDevice(g));
    static_host_reset(g, s.stream, g_launches);
    if (STATIC_PROFILE) {
      ST_CK(cudaMemsetAsync(s.times,
                            0,
                            static_times_count * sizeof(unsigned long long),
                            s.stream));
    }
  }
#ifndef STATIC_RESET_IN_KERNEL
  (void)flush_bytes;
  for (int g = 0; g < n; g++) {
    ST_CK(cudaSetDevice(g));
    ST_CK(cudaStreamSynchronize(g_st[g].stream));
  }
#endif
  for (int gpu = 0; gpu < n; gpu++) {
    StaticGpu &s = g_st[gpu];
    ST_CK(cudaSetDevice(gpu));
#ifdef STATIC_RESET_IN_KERNEL
    static_host_prelude(gpu, s.stream, flush_bytes, (unsigned)(g_launches + 1));
#endif
    ST_CK(cudaEventRecord(s.start, s.stream));
    layer_kernel<<<static_mk::NSM, 256, (int)(STATIC_SMEM_BYTES), s.stream>>>(
        static_host::g_gpus[gpu].maps,
        static_host::g_gpus[gpu].g,
        s.tasks STATIC_TIMES_ARG);
    ST_CK(cudaGetLastError());
    ST_CK(cudaEventRecord(s.end, s.stream));
  }
  g_launches++;
}

// per GPU the time between the last launch's two events, in microseconds (after
// static_wait)
static cudaError_t static_elapsed(std::vector<float> &us) {
  us.assign(g_st.size(), 0.f);
  for (size_t g = 0; g < g_st.size(); g++) {
    ST_CK(cudaSetDevice((int)g));
    float ms = 0.f;
    cudaError_t const e = cudaEventElapsedTime(&ms, g_st[g].start, g_st[g].end);
    if (e != cudaSuccess) {
      return e;
    }
    us[g] = ms * 1000.f;
  }
  return cudaSuccess;
}

// wait for every GPU's end event
static cudaError_t static_wait() {
  for (size_t g = 0; g < g_st.size(); g++) {
    ST_CK(cudaSetDevice((int)g));
    cudaError_t const e = cudaEventSynchronize(g_st[g].end);
    if (e != cudaSuccess) {
      return e;
    }
  }
  return cudaSuccess;
}

// whether every GPU's end event has passed (no wait)
static cudaError_t static_done(bool *done) {
  *done = true;
  for (size_t g = 0; g < g_st.size(); g++) {
    ST_CK(cudaSetDevice((int)g));
    cudaError_t const e = cudaEventQuery(g_st[g].end);
    if (e == cudaErrorNotReady) {
      *done = false;
    } else if (e != cudaSuccess) {
      return e;
    }
  }
  return cudaSuccess;
}

// GPU g's instrumentation buffer `name` (the kernel's: host.cuh
// static_host_buffer; the timing build's "task_times"), copied on a
// non-blocking stream (readable while a launch has not finished)
static cudaError_t
    static_read(int g, std::string const &name, std::vector<char> &out) {
  void const *p = nullptr;
  size_t bytes = 0;
  if (name == "task_times" && STATIC_PROFILE) {
    p = g_st[g].times;
    bytes = static_times_count * sizeof(unsigned long long);
  } else {
    static_host_buffer(g, name, p, bytes);
  }
  if (!p) {
    return cudaErrorInvalidValue;
  }
  out.resize(bytes);
  ST_CK(cudaSetDevice(g));
  cudaStream_t nb;
  cudaError_t e = cudaStreamCreateWithFlags(&nb, cudaStreamNonBlocking);
  if (e != cudaSuccess) {
    return e;
  }
  e = cudaMemcpyAsync(out.data(), p, bytes, cudaMemcpyDeviceToHost, nb);
  if (e == cudaSuccess) {
    e = cudaStreamSynchronize(nb);
  }
  cudaStreamDestroy(nb);
  return e;
}

static void static_finalize() {
  static_host_finalize(g_ctx);
  for (size_t g = 0; g < g_st.size(); g++) {
    StaticGpu &s = g_st[g];
    cudaSetDevice((int)g);
    if (s.tasks) {
      cudaFree(s.tasks);
    }
    if (s.times) {
      cudaFree(s.times);
    }
    cudaEventDestroy(s.start);
    cudaEventDestroy(s.end);
    cudaStreamDestroy(s.stream);
  }
  g_st.clear();
}

// ---- Python binding: module __mirage_static_launcher ----
static PyObject *py_init(PyObject *self, PyObject *args) {
  PyObject *py_names, *py_ptrs;
  if (!PyArg_ParseTuple(args, "OO", &py_names, &py_ptrs)) {
    return NULL;
  }
  if (!PyList_Check(py_names) || !PyList_Check(py_ptrs) ||
      PyList_Size(py_names) != PyList_Size(py_ptrs)) {
    PyErr_SetString(PyExc_TypeError, "names / pointers: one list per GPU");
    return NULL;
  }
  std::vector<std::map<std::string, void *>> tensors(PyList_Size(py_names));
  for (Py_ssize_t g = 0; g < PyList_Size(py_names); g++) {
    PyObject *nl = PyList_GetItem(py_names, g),
             *pl = PyList_GetItem(py_ptrs, g);
    if (!PyList_Check(nl) || !PyList_Check(pl) ||
        PyList_Size(nl) != PyList_Size(pl)) {
      PyErr_SetString(PyExc_TypeError, "bad tensor lists");
      return NULL;
    }
    for (Py_ssize_t i = 0; i < PyList_Size(nl); i++) {
      char const *s = PyUnicode_AsUTF8(PyList_GetItem(nl, i));
      if (!s) {
        return NULL;
      }
      tensors[g][s] = PyLong_AsVoidPtr(PyList_GetItem(pl, i));
    }
  }
  if (PyErr_Occurred()) {
    return NULL;
  }
  static_init(tensors);
  Py_RETURN_NONE;
}
static PyObject *py_launch(PyObject *self, PyObject *args) {
  unsigned long long flush_bytes = 0;
  if (!PyArg_ParseTuple(args, "|K", &flush_bytes)) {
    return NULL;
  }
  static_launch((size_t)flush_bytes);
  Py_RETURN_NONE;
}
static PyObject *py_elapsed(PyObject *self, PyObject *args) {
  std::vector<float> us;
  cudaError_t const err = static_elapsed(us);
  if (err != cudaSuccess) {
    PyErr_Format(PyExc_RuntimeError,
                 "event times not readable: %s",
                 cudaGetErrorString(err));
    return NULL;
  }
  PyObject *out = PyList_New((Py_ssize_t)us.size());
  for (size_t g = 0; g < us.size(); g++) {
    PyList_SetItem(out, (Py_ssize_t)g, PyFloat_FromDouble(us[g]));
  }
  return out;
}
static PyObject *py_wait(PyObject *self, PyObject *args) {
  cudaError_t err;
  Py_BEGIN_ALLOW_THREADS err = static_wait();
  Py_END_ALLOW_THREADS if (err != cudaSuccess) {
    PyErr_Format(
        PyExc_RuntimeError, "layer kernel failed: %s", cudaGetErrorString(err));
    return NULL;
  }
  Py_RETURN_NONE;
}
static PyObject *py_done(PyObject *self, PyObject *args) {
  bool done = false;
  cudaError_t const err = static_done(&done);
  if (err != cudaSuccess) {
    PyErr_Format(
        PyExc_RuntimeError, "layer kernel failed: %s", cudaGetErrorString(err));
    return NULL;
  }
  return PyBool_FromLong(done);
}
static PyObject *py_read(PyObject *self, PyObject *args) {
  int g;
  char const *name;
  if (!PyArg_ParseTuple(args, "is", &g, &name)) {
    return NULL;
  }
  if (g < 0 || g >= (int)g_st.size()) {
    PyErr_Format(
        PyExc_IndexError, "GPU %d: the layer runs on %zu", g, g_st.size());
    return NULL;
  }
  std::vector<char> h;
  cudaError_t const err = static_read(g, name, h);
  if (err == cudaErrorInvalidValue) {
    PyErr_Format(PyExc_KeyError, "no instrumentation buffer %s", name);
    return NULL;
  }
  if (err != cudaSuccess) {
    PyErr_Format(PyExc_RuntimeError,
                 "%s of GPU %d not readable: %s",
                 name,
                 g,
                 cudaGetErrorString(err));
    return NULL;
  }
  return PyBytes_FromStringAndSize(h.data(), (Py_ssize_t)h.size());
}
// the sizes a test harness needs to read the instrumentation buffers
// (config.cuh, and the timing build's per-entry slots)
static PyObject *py_layout(PyObject *self, PyObject *args) {
  using namespace static_mk;
#ifdef STATIC_RESET_IN_KERNEL
  PyObject *const serving = Py_True;
#else
  PyObject *const serving = Py_False;
#endif
  return Py_BuildValue(
      "{s:i,s:i,s:i,s:i,s:i,s:i,s:i,s:i,s:i,s:O,s:i,s:i,s:i,s:O}",
      "num_gpus",
      static_mk::GPUS,
      "num_sms",
      static_mk::NSM,
      "counter_lines",
      NODE_COUNTER_LINES,
      "counters_per_line",
      NCNT / NODE_COUNTER_LINES,
      "num_stamps",
      NSTAMP,
      "stamp_start",
      STAMP_START,
      "stamp_task0",
      STAMP_TASK0,
      "stamp_task1",
      STAMP_TASK1,
      "stamp_end",
      STAMP_END,
      "profile",
      STATIC_PROFILE ? Py_True : Py_False,
      "max_tasks",
      (int)(static_mk::MAX_TASKS_PER_SM),
      "time_slots",
      11,
      "warps",
      8,
      "serving",
      serving);
}
static PyObject *py_finalize(PyObject *self, PyObject *args) {
  static_finalize();
  Py_RETURN_NONE;
}
static PyMethodDef StaticMethods[] = {
    {"init_func",
     py_init,
     METH_VARARGS,
     "the graph's tensors of every GPU (names, pointers): the buffers and "
     "maps"},
    {"launch_func",
     py_launch,
     METH_VARARGS,
     "one launch on every GPU ([flush bytes]: serving mode, L2 emptied on the "
     "stream first)"},
    {"elapsed_func",
     py_elapsed,
     METH_NOARGS,
     "per GPU the microseconds between the events around the last launch's "
     "kernel"},
    {"wait_func", py_wait, METH_NOARGS, "wait for every GPU"},
    {"done_func",
     py_done,
     METH_NOARGS,
     "whether every GPU has finished the last launch (no wait)"},
    {"read_func",
     py_read,
     METH_VARARGS,
     "(gpu, name): an instrumentation buffer's bytes (also while a launch has "
     "not finished)"},
    {"layout_func",
     py_layout,
     METH_NOARGS,
     "the sizes of the instrumentation buffers"},
    {"finalize_func", py_finalize, METH_NOARGS, "free everything"},
    {NULL, NULL, 0, NULL}};
static struct PyModuleDef StaticModuleDef = {PyModuleDef_HEAD_INIT,
                                             "__mirage_static_launcher",
                                             NULL,
                                             -1,
                                             StaticMethods,
                                             NULL,
                                             NULL,
                                             NULL,
                                             NULL};
PyMODINIT_FUNC PyInit___mirage_static_launcher(void) {
  return PyModule_Create(&StaticModuleDef);
}
